from pathlib import Path
import nbformat as nb
r=Path(__file__).resolve().parents[1];n=nb.v4.new_notebook();n.metadata.kernelspec={'display_name':'Python 3','language':'python','name':'lecture-lab'}
md=lambda s:nb.v4.new_markdown_cell(s);code=lambda s:nb.v4.new_code_cell(s)
n.cells=[md('# Learning to generate: executable lab\nES 667 · Nipun Batra · IIT Gandhinagar\n\n45–60 minutes. CPU, offline procedural binary glyphs. Run from the repository root or notebooks folder. See LAB.md for student questions and ANSWERS.md after attempting them.'),code('from pathlib import Path\nimport sys, json, subprocess, math\nimport torch\nfrom torch.nn import functional as F\nROOT = Path.cwd() if (Path.cwd()/"src/math.mjs").exists() else Path.cwd().parent\nsys.path.insert(0, str(ROOT/"notebooks"))\nfrom models import TinyVAE, vae_step, sample_vae, make_image_gan, gan_step\nfrom train import glyphs\nfrom validate import validate\ntorch.set_num_threads(2)\ntorch.manual_seed(667)\nprint("PyTorch", torch.__version__)'),md('## 1. Shared exact quantities\nThe JavaScript module is the same module used by the lecture. Compare both KL directions and explain the posterior gap.'),code('fixture = json.loads(subprocess.check_output(["node", str(ROOT/"src/math.mjs")]))\nprint(json.dumps(fixture, indent=2))\nassert abs(fixture["finite"]["elbo"] + fixture["finite"]["gap"] - fixture["finite"]["logEvidence"]) < 1e-10'),md('## 2. One pathwise derivative\nKeep epsilon fixed. Then compare many samples with the expected gradient.'),code('mu = torch.tensor(1., dtype=torch.float64, requires_grad=True)\nlogvar = torch.tensor(math.log(.25), dtype=torch.float64, requires_grad=True)\neps = torch.tensor(-.4, dtype=torch.float64)\nz = mu + (logvar/2).exp()*eps\nloss = z.square()\nloss.backward()\nprint("sample, loss, dmu, dlogvar:", z.item(), loss.item(), mu.grad.item(), logvar.grad.item())\nassert abs(mu.grad.item()-1.6)<1e-10\nassert abs(logvar.grad.item()+.16)<1e-10'),code('mu.grad = None; logvar.grad = None\neps = torch.randn(10000, generator=torch.Generator().manual_seed(19), dtype=torch.float64)\n((mu + (logvar/2).exp()*eps).square().mean()).backward()\nprint("estimated gradients:", mu.grad.item(), logvar.grad.item())\nprint("exact expected gradients:", 2*mu.item(), logvar.exp().item())'),md('## 3. Train one VAE step and inspect the recorded model\nThis short step is a smoke demonstration. The saved model below was trained for 65 epochs. Displaying decoder probabilities differs from sampling its Bernoulli likelihood.'),code('model = TinyVAE()\nx = glyphs(128)\noptimizer = torch.optim.Adam(model.parameters(), lr=.001)\nprint("one fresh update:", vae_step(model, optimizer, x))\nmodel.load_state_dict(torch.load(ROOT/"models/vae.pt", map_location="cpu", weights_only=True))\nwith torch.no_grad():\n    mu, logvar = model.encode(x[:8])\n    reconstruction = model.decode(mu).sigmoid().reshape(-1,1,28,28)\n    probabilities = sample_vae(model, count=8, sample_pixels=False)\n    binary_samples = sample_vae(model, count=8, sample_pixels=True)\nprint(reconstruction.shape, probabilities.shape, binary_samples.unique().tolist())'),code('from IPython.display import display, Image\ndisplay(Image(filename=str(ROOT/"assets/recorded/held-out.png")))\ndisplay(Image(filename=str(ROOT/"assets/recorded/reconstructions.png")))\ndisplay(Image(filename=str(ROOT/"assets/recorded/vae-prior.png")))'),md('## 4. Alternating GAN updates\nRun the real gradient-isolation checks. They include the deliberately broken detach diagnostic. Inspect the complete `gan_step` function in models.py.'),code('G,D = make_image_gan()\noptG = torch.optim.Adam(G.parameters(), lr=2e-4, betas=(.5,.999))\noptD = torch.optim.Adam(D.parameters(), lr=2e-4, betas=(.5,.999))\nprint(gan_step(G,D,optG,optD,glyphs(16)))\nreport = validate()\nassert report["passed"] == 14'),code('run = json.loads((ROOT/"assets/recorded/gan.json").read_text())\nfor frame in run["frames"]:\n    points = torch.tensor(frame["samples"])\n    centres = torch.tensor([[-2.,0.],[2.,0.]])\n    close = torch.cdist(points,centres) < .65\n    print(frame["step"], "realism", close.any(1).float().mean().item(), "coverage", (close.sum(0)>=5).sum().item(), frame["loss"])'),md('## Optional full rerun\nRun `python notebooks/train.py --epochs 65 --steps 1800` from the repository root. This replaces the recorded artifacts with a fresh seeded run. Training time and bitwise results can vary by environment. No GPU or paid API is needed.\n\n**Exit:** explain why a plausible sample is insufficient evidence of distribution coverage.')]
nb.write(n,r/'notebooks/lecture-lab.ipynb')
